// A collection served inside an autogenerated folder's URL is placed in that
// folder: as a group with its landing page, ordered among the folder's pages,
// collapsed or hidden by its own `index` page.

import assert from "node:assert/strict";
import { describe, test } from "node:test";

import {
  applyOverviewLeaf,
  buildSidebarTree,
  findActivePath,
  flattenSidebar,
  isolateToBoundary,
  scopeToCurrentSection,
  type NestedCollection,
} from "../src/_internal/sidebar.js";
import type { SidebarConfig, SidebarItem } from "../src/types.js";

type Data = { title?: string; draft?: boolean; external_link?: string; hideChildren?: boolean; sidebar?: Record<string, unknown> };
type Entry = { id: string; data: Data };

const titleOf = (id: string) => {
  const last = id.split("/").at(-1)!;
  return last === "index" ? id : last[0]!.toUpperCase() + last.slice(1);
};
const page = (id: string, data: Data = {}): Entry => ({ id, data: { title: titleOf(id), ...data } });
const nested = (collection: string, mount: string, entries: Entry[]) =>
  ({ collection, mount, entries }) as unknown as NestedCollection;

const integrations = [
  page("integrations", { title: "Integrations" }),
  page("integrations/connectors", { title: "Connectors" }),
  page("integrations/connectors/kafka"),
  page("integrations/connectors/zapier"),
  page("guides/start"),
];
const dbt = (mount = "/integrations/connectors/dbt", entries = [page("index", { title: "dbt" }), page("setup"), page("usage")]) =>
  nested("dbt", mount, entries);

function build(docs: Entry[], collections: NestedCollection[] = [], config?: SidebarConfig, path = "/x"): SidebarItem[] {
  return buildSidebarTree({ docs } as never, "docs", path, config, "", new Set(), undefined, collections);
}

// One line per node: `[Label] /landing/` for groups, `Label /href/` for links.
function outline(items: SidebarItem[], indent = ""): string[] {
  return items.flatMap((item) => {
    if (item.type === "group") {
      const head = `${indent}[${item.label}]${item.indexHref ? ` ${item.indexHref}` : ""}`;
      return [head, ...outline(item.children, `${indent}  `)];
    }
    return [`${indent}${item.label} ${item.href}`];
  });
}

const find = (items: SidebarItem[], label: string): Extract<SidebarItem, { type: "group" }> | undefined => {
  for (const item of items) {
    if (item.type !== "group") continue;
    if (item.label === label) return item;
    const inner = find(item.children, label);
    if (inner) return inner;
  }
  return undefined;
};

describe("placement", () => {
  test("a collection nested in a docs folder appears inside it, with its landing", () => {
    const tree = build(integrations, [dbt()]);
    assert.deepEqual(outline(tree), [
      "[Guides]",
      "  Start /guides/start/",
      "[Integrations] /integrations/",
      "  [Connectors] /integrations/connectors/",
      "    [dbt] /integrations/connectors/dbt/",
      "      Setup /integrations/connectors/dbt/setup/",
      "      Usage /integrations/connectors/dbt/usage/",
      "    Kafka /integrations/connectors/kafka/",
      "    Zapier /integrations/connectors/zapier/",
    ]);
    assert.deepEqual(
      findActivePath(tree, "/integrations/connectors/dbt/setup").map((n) => n.label),
      ["Integrations", "Connectors", "dbt", "Setup"],
    );
    const flat = flattenSidebar(tree).map((l) => l.href);
    assert.deepEqual(flat.slice(flat.indexOf("/integrations/connectors/")), [
      "/integrations/connectors/",
      "/integrations/connectors/dbt/",
      "/integrations/connectors/dbt/setup/",
      "/integrations/connectors/dbt/usage/",
      "/integrations/connectors/kafka/",
      "/integrations/connectors/zapier/",
    ]);
  });

  test("the same placement under a docs autogenerate and a labeled directory autogenerate", () => {
    const expected = outline(build(integrations, [dbt()])).filter((line) => !line.includes("uides"));
    const viaCollection = outline(build(integrations, [dbt()], { items: [{ autogenerate: { collection: "docs" } }] }));
    assert.deepEqual(viaCollection.filter((line) => !line.includes("uides")), expected);
    const labeled = outline(
      build(integrations, [dbt()], { items: [{ label: "Integrations", autogenerate: { directory: "integrations" } }] }),
    );
    assert.deepEqual(labeled, [
      "[Integrations]",
      "  [Connectors] /integrations/connectors/",
      "    [dbt] /integrations/connectors/dbt/",
      "      Setup /integrations/connectors/dbt/setup/",
      "      Usage /integrations/connectors/dbt/usage/",
      "    Kafka /integrations/connectors/kafka/",
      "    Zapier /integrations/connectors/zapier/",
      "  Integrations /integrations/",
    ]);
  });

  test("an inline directory expansion takes the collection without moving the configured items around it", () => {
    const docs = [page("index", { title: "Intro" }), page("integrations/zapier"), page("integrations/kafka", { sidebar: { order: 5 } })];
    const expansion = { autogenerate: { directory: "integrations" } } as const;
    const config = {
      items: [{ label: "Docs", items: [{ label: "Intro", link: "/" }, expansion, { label: "Changelog", link: "/changelog" }] }],
    } as SidebarConfig;
    const collection = dbt("/integrations/dbt", [page("setup", { sidebar: { order: 1 } })]);
    assert.deepEqual(outline(build(docs, [collection], config)), [
      "[Docs]",
      "  Intro /",
      "  [Dbt]",
      "    Setup /integrations/dbt/setup/",
      "  Kafka /integrations/kafka/",
      "  Zapier /integrations/zapier/",
      "  Changelog /changelog/",
    ]);
    const twice = {
      items: [{ label: "Docs", items: [expansion] }, { label: "Again", items: [expansion] }],
    } as SidebarConfig;
    assert.deepEqual(outline(build(docs, [collection], twice)), [
      "[Docs]",
      "  [Dbt]",
      "    Setup /integrations/dbt/setup/",
      "  Kafka /integrations/kafka/",
      "  Zapier /integrations/zapier/",
      "[Again]",
      "  Kafka /integrations/kafka/",
      "  Zapier /integrations/zapier/",
    ]);
  });
});

describe("route keys", () => {
  test("a placed group's key is its mount, whatever the collection is called", () => {
    const group = find(build(integrations, [nested("tools", "/integrations/connectors/dbt", [page("setup")])]), "Dbt")!;
    assert.equal(group._routeKey, "/integrations/connectors/dbt/");
    assert.equal(group.children[0]!.type === "link" && group.children[0].href, "/integrations/connectors/dbt/setup/");
  });

  test("ancestry compares whole segments, and trailing slashes don't matter", () => {
    const tree = build(integrations, [dbt("/integrations/connectors-extra/x/")]);
    const extra = find(tree, "dbt")!;
    assert.equal(find(tree, "Integrations")!.children.includes(extra), true);
    assert.equal(find(tree, "Connectors")!.children.includes(extra), false);
    assert.equal(extra._routeKey, "/integrations/connectors-extra/x/");
  });
});

describe("the collection's index page", () => {
  const docs = [page("products/a", { sidebar: { order: 2 } }), page("products/b", { sidebar: { order: 3 } })];
  const products = (entries: Entry[]) => find(build(docs, [nested("sdk", "/products/sdk", entries)]), "Products")!;

  test("an empty candidate changes nothing, beside a folder or a lone landing page", () => {
    const empty = nested("sdk", "/products/sdk", [page("index", { sidebar: { order: 1, group: { hideIndex: true } } })]);
    assert.deepEqual(build(docs, [empty]), build(docs));
    const lone = [page("products", { title: "Products", sidebar: { order: 4 } }), page("guide")];
    assert.deepEqual(build(lone, [empty]), build(lone));
    assert.deepEqual(build(lone, [nested("sdk", "/products/sdk", [page("index", { draft: true, sidebar: { hidden: true } })])]), build(lone));
  });

  test("group label and order come from the index page, else its title and lowest child", () => {
    const labeled = products([page("index", { title: "SDK", sidebar: { order: 1, group: { label: "Kit" } } }), page("x")]);
    assert.deepEqual(labeled.children.map((c) => c.label), ["Kit", "A", "B"]);
    const inherited = products([page("index", { title: "SDK" }), page("x", { sidebar: { order: 1 } })]);
    assert.deepEqual(inherited.children.map((c) => c.label), ["SDK", "A", "B"]);
  });

  test("no index makes a header; hideIndex drops the landing but keeps the header", () => {
    const bare = find(products([page("x")]).children, "Sdk")!;
    assert.equal(bare.indexHref, undefined);
    const hidden = find(products([page("index", { title: "SDK", sidebar: { group: { hideIndex: true } } }), page("x")]).children, "SDK")!;
    assert.equal(hidden.indexHref, undefined);
    assert.equal(hidden.children.length, 1);
  });

  test("an external_link landing behaves as a folder's", () => {
    const off = find(products([page("index", { title: "SDK", external_link: "https://example.com" }), page("x")]).children, "SDK")!;
    assert.equal(off.indexIsExternal, true);
    const across = find(products([page("index", { title: "SDK", external_link: "/elsewhere" }), page("x")]).children, "SDK")!;
    assert.equal(across._indexNeverActive, true);
    const tree = build(docs, [nested("sdk", "/products/sdk", [page("index", { title: "SDK", external_link: "https://example.com" }), page("x")])]);
    assert.ok(!flattenSidebar(tree).some((l) => l.href === "https://example.com"));
  });

  test("hideChildren shows only the landing; sidebar.hidden leaves it out", () => {
    const collapsed = products([page("index", { title: "SDK", sidebar: { hideChildren: true } }), page("x")]);
    const link = collapsed.children.find((c) => c.label === "SDK")!;
    assert.equal(link.type, "link");
    const left = products([page("index", { title: "SDK", sidebar: { hidden: true } }), page("x")]);
    assert.deepEqual(left.children.map((c) => c.label), ["A", "B"]);
  });

  test("a draft index is a landing when it's in the entries, and all-hidden collections aren't placed", () => {
    const dev = find(products([page("index", { title: "SDK", draft: true }), page("x")]).children, "SDK")!;
    assert.equal(dev.indexHref, "/products/sdk/");
    const prod = find(products([page("x")]).children, "Sdk")!;
    assert.equal(prod.indexHref, undefined);
    const allHidden = products([page("x", { sidebar: { hidden: true } })]);
    assert.deepEqual(allHidden.children.map((c) => c.label), ["A", "B"]);
  });
});

describe("hideChildren ownership", () => {
  test("each group collapses by its own collection's index page", () => {
    const docs = [page("products/guides", { title: "Guides" }), page("products/guides/one"), page("products/x")];
    const sdk = nested("sdk", "/products/sdk", [
      page("index", { title: "SDK" }),
      page("guides", { title: "SDK guides", sidebar: { hideChildren: true } }),
      page("guides/two"),
    ]);
    const cli = nested("cli", "/products/cli", [page("index", { title: "CLI", hideChildren: true }), page("run")]);
    const tree = build(docs, [sdk, cli]);
    assert.equal(find(tree, "Guides")!.children.length, 1);
    assert.equal(find(tree, "SDK")!.children.find((c) => c.label === "SDK guides")!.type, "link");
    assert.equal(find(tree, "Products")!.children.find((c) => c.label === "CLI")!.type, "link");

    const reversed = build(
      [page("products/guides", { title: "Guides", sidebar: { hideChildren: true } }), page("products/guides/one")],
      [nested("sdk", "/products/sdk", [page("index", { title: "SDK" }), page("guides", { title: "SDK guides" }), page("guides/two")])],
    );
    assert.equal(find(reversed, "Products")!.children.find((c) => c.label === "Guides")!.type, "link");
    assert.equal(find(reversed, "SDK guides")!.children.length, 1);
  });

  test("a collapsed docs folder hides a collection inside it; one with no target changes nothing", () => {
    const docs = [page("products", { title: "Products", hideChildren: true }), page("products/x")];
    const tree = build(docs, [nested("sdk", "/products/sdk", [page("index", { title: "SDK" }), page("y")])]);
    assert.deepEqual(outline(tree), ["Products /products/"]);
    const orphan = nested("dbt", "/nowhere/dbt", [page("index", { title: "dbt", hideChildren: true }), page("y")]);
    assert.deepEqual(build(integrations, [orphan]), build(integrations));
  });
});

describe("order", () => {
  test("an index-less folder takes its placed child's order; an explicit order doesn't move", () => {
    const docs = [page("a/one", { sidebar: { order: 5 } }), page("b/two", { sidebar: { order: 3 } })];
    const sdk = nested("sdk", "/a/sdk", [page("x", { sidebar: { order: 1 } })]);
    assert.deepEqual(build(docs, [sdk]).map((i) => i.label), ["A", "B"]);
    const pinned = [page("a", { title: "A", sidebar: { order: 9 } }), ...docs];
    assert.deepEqual(build(pinned, [sdk]).map((i) => i.label), ["B", "A"]);
  });

  test("an index-less placed collection takes the order of a collection nested in it", () => {
    const docs = [page("products/a", { sidebar: { order: 2 } })];
    const sdk = nested("sdk", "/products/sdk", [page("x", { sidebar: { order: 9 } })]);
    const cli = nested("cli", "/products/sdk/cli", [page("run", { sidebar: { order: 1 } })]);
    const products = find(build(docs, [cli, sdk]), "Products")!;
    assert.deepEqual(products.children.map((c) => c.label), ["Sdk", "A"]);
    assert.deepEqual(find(products.children, "Sdk")!.children.map((c) => c.label), ["Cli", "X"]);
  });
});

describe("deep mounts and missing folders", () => {
  const docs = [page("products/one"), page("integrations/connectors/data-ingestion/kafka")];
  const privateEdition = nested("private", "/products/private-edition", [page("index", { title: "Private" }), page("a")]);
  const deepDbt = nested("dbt", "/integrations/connectors/data-ingestion/etl-tools/dbt", [page("index", { title: "dbt" })]);

  test("the deepest existing folder takes a collection whose middle folders are missing", () => {
    const tree = build(docs, [privateEdition, deepDbt]);
    assert.ok(find(tree, "Products")!.children.some((c) => c.label === "Private"));
    assert.ok(find(tree, "Data Ingestion")!.children.some((c) => c.label === "dbt"));
  });

  test("a folder's lone index page becomes a group holding the collection", () => {
    const lone = [page("products", { title: "Products", sidebar: { order: 2 } }), page("guide", { sidebar: { order: 1 } })];
    assert.deepEqual(outline(build(lone, [privateEdition])), [
      "Guide /guide/",
      "[Products] /products/",
      "  [Private] /products/private-edition/",
      "    A /products/private-edition/a/",
    ]);
    const labeled = build(lone, [privateEdition], { items: [{ label: "Products", autogenerate: { directory: "products" } }] });
    assert.deepEqual(outline(labeled), [
      "[Products]",
      "  Products /products/",
      "  [Private] /products/private-edition/",
      "    A /products/private-edition/a/",
    ]);
    const inline = build(lone, [privateEdition], { items: [{ label: "Docs", items: [{ autogenerate: { directory: "products" } }] }] });
    assert.deepEqual(outline(inline), [
      "[Docs]",
      "  Products /products/",
      "  [Private] /products/private-edition/",
      "    A /products/private-edition/a/",
    ]);
  });
});

describe("a promoted folder", () => {
  test("keeps the page's link label, and otherwise follows folder rules, as with a second page", () => {
    const lone = [page("products", { title: "Products", sidebar: { label: "All products" } }), page("guide", { sidebar: { order: 2 } })];
    const sdk = nested("sdk", "/products/sdk", [page("x", { sidebar: { order: 1 } })]);
    assert.deepEqual(outline(build(lone)), ["Guide /guide/", "All products /products/"]);
    assert.deepEqual(outline(build(lone, [sdk])), [
      "[All products] /products/",
      "  [Sdk]",
      "    X /products/sdk/x/",
      "Guide /guide/",
    ]);
    const twoPages = [...lone, page("products/other", { sidebar: { order: 1 } })];
    const { children: _promoted, label: promotedLabel, ...promoted } = find(build(lone, [sdk]), "All products")!;
    const { children: _folder, label: folderLabel, ...folder } = find(build(twoPages), "Products")!;
    assert.deepEqual(promoted, folder);
    assert.deepEqual([promotedLabel, folderLabel], ["All products", "Products"]);
    const renamed = [page("products", { title: "Products", sidebar: { label: "All products", group: { label: "Catalog" } } })];
    assert.equal(build(renamed, [sdk])[0]!.label, "Catalog");
  });
});

describe("nesting", () => {
  const docs = [page("products/x")];
  const cli = nested("cli", "/products/sdk/cli", [page("index", { title: "CLI" }), page("run")]);
  const sdk = (index: Data, pages = [page("y")]) => nested("sdk", "/products/sdk", [page("index", { title: "SDK", ...index }), ...pages]);

  test("a collection nested in a placed collection goes inside it", () => {
    assert.deepEqual(outline(build(docs, [cli, sdk({})])), [
      "[Products]",
      "  [SDK] /products/sdk/",
      "    [CLI] /products/sdk/cli/",
      "      Run /products/sdk/cli/run/",
      "    Y /products/sdk/y/",
      "  X /products/x/",
    ]);
  });

  test("the outer collection's index hides, collapses or demotes it, and a hidden one takes it along", () => {
    assert.deepEqual(outline(build(docs, [cli, sdk({ sidebar: { hideChildren: true } })])), [
      "[Products]",
      "  SDK /products/sdk/",
      "  X /products/x/",
    ]);
    assert.deepEqual(outline(build(docs, [cli, sdk({ sidebar: { hidden: true } })])), ["[Products]", "  X /products/x/"]);
    assert.deepEqual(outline(build(docs, [cli, sdk({ sidebar: { group: { hideIndex: true } } }, [])])), [
      "[Products]",
      "  [SDK]",
      "    [CLI] /products/sdk/cli/",
      "      Run /products/sdk/cli/run/",
      "  X /products/x/",
    ]);
  });
});

describe("inside a collection placed by hand", () => {
  const docs = [page("products/x")];
  const cli = nested("cli", "/products/sdk/cli", [page("index", { title: "CLI" }), page("run")]);
  const entries = { docs, sdk: [page("index", { title: "SDK" }), page("y")] } as never;
  const mount = (c: string) => (c === "sdk" ? "/products/sdk" : `/${c}`);
  const tree = (items: SidebarConfig["items"], path = "/x") =>
    outline(buildSidebarTree(entries, "docs", path, { items } as SidebarConfig, "", new Set(), mount, [cli]));
  const docsItems = { autogenerate: { collection: "docs" } } as const;

  test("a labeled group links the landing and holds the collections inside it", () => {
    assert.deepEqual(tree([{ label: "Tools", autogenerate: { collection: "sdk" } }, docsItems]), [
      "[Tools] /products/sdk/",
      "  [CLI] /products/sdk/cli/",
      "    Run /products/sdk/cli/run/",
      "  Y /products/sdk/y/",
      "[Products]",
      "  X /products/x/",
    ]);
  });

  test("an inline expansion holds the collections inside it", () => {
    assert.deepEqual(tree([{ label: "Tools", items: [{ autogenerate: { collection: "sdk" } }] }, docsItems]), [
      "[Tools]",
      "  [CLI] /products/sdk/cli/",
      "    Run /products/sdk/cli/run/",
      "  Y /products/sdk/y/",
      "[Products]",
      "  X /products/x/",
    ]);
  });

  test("a link to the outer collection keeps the inner one out", () => {
    const sdk = nested("sdk", "/products/sdk", [page("index", { title: "SDK" }), page("y")]);
    const config = { items: [{ label: "SDK", link: "/products/sdk/" }, docsItems] } as SidebarConfig;
    assert.deepEqual(outline(build(docs, [cli, sdk], config)), ["SDK /products/sdk/", "[Products]", "  X /products/x/"]);
  });
});

describe("not placed", () => {
  test("a collection with no enclosing folder", () => {
    assert.deepEqual(build(integrations, [dbt("/elsewhere/dbt")]), build(integrations));
  });

  test("a collection the config places by hand stays there", () => {
    const config = { items: [{ label: "dbt", items: [{ autogenerate: { collection: "dbt" } }] }] } as SidebarConfig;
    const entries = { docs: integrations, dbt: dbt().entries } as never;
    const mount = (c: string) => (c === "dbt" ? "/integrations/connectors/dbt" : `/${c}`);
    const tree = buildSidebarTree(entries, "docs", "/x", config, "", new Set(), mount);
    assert.deepEqual(outline(tree), [
      "[dbt]",
      "  Setup /integrations/connectors/dbt/setup/",
      "  Usage /integrations/connectors/dbt/usage/",
    ]);
  });

  test("a link to the collection, or a hand-made group landing on it, places it by hand", () => {
    const docsItems = { autogenerate: { collection: "docs" } } as const;
    for (const config of [
      { items: [{ label: "dbt", link: "/integrations/connectors/dbt/" }, docsItems] },
      { items: [{ label: "dbt", link: "/integrations/connectors/dbt" }, docsItems] },
      { items: [{ label: "Tools", landing: "/integrations/connectors/dbt/", items: [{ label: "Kafka", link: "/kafka" }] }, docsItems] },
    ] as SidebarConfig[]) {
      const tree = build(integrations, [dbt()], config, "/integrations/connectors/dbt/");
      assert.ok(!outline(tree).some((line) => line.includes("[dbt]")), JSON.stringify(config));
      assert.equal(outline(tree).filter((line) => line.includes("/integrations/connectors/dbt/setup/")).length, 0);
    }
  });
});

describe("the rest of navigation follows the tree", () => {
  const setup = "/integrations/connectors/dbt/setup";

  test("section scope and isolation", () => {
    const tree = build(integrations, [dbt()]);
    const scoped = scopeToCurrentSection(tree, setup);
    assert.ok(find(scoped, "dbt"));
    const isolated = isolateToBoundary(scoped, setup, ["integrations/connectors/dbt"]);
    assert.deepEqual(isolated.map((i) => i.label), ["dbt", "Setup", "Usage"]);
  });

  test("overview-leaf, overviewLabel and defaultCollapsed", () => {
    const leaf = applyOverviewLeaf(scopeToCurrentSection(build(integrations, [dbt()]), setup), "integrations", "Overview");
    assert.deepEqual(find(leaf, "dbt")!.children.map((c) => c.label), ["Overview", "Setup", "Usage"]);
    const collapsed = build(integrations, [dbt()], { defaultCollapsed: true } as SidebarConfig);
    assert.equal(find(collapsed, "dbt")!.collapsed, true);
    const labeled = build(integrations, [dbt()], {
      items: [{ label: "Integrations", autogenerate: { directory: "integrations" } }],
      overviewLabel: true,
    } as SidebarConfig);
    assert.deepEqual(find(labeled, "Integrations")!.children.map((c) => c.label), ["Connectors", "Overview"]);
    assert.ok(find(labeled, "dbt"));
  });
});
